    expect([all("shut-cave", voices, 0.48), all("shut-cave", pictures, 0.48), all("shut-cave", milk, 0.48), value("shut-cave", "the rock", "x", 0.48)]).toEqual([[0, 0, 0], [0, 0, 0], milk.map(() => 0), 3.4]);
