    expect([hungry.map((name) => at("hungry-birds", name, 0.62)), all("hungry-birds", grain, 0.62), shown("hungry-birds", "the dawn sky", 0.62), all("hungry-birds", full, 0.62)]).toEqual([[[1, 86, 31.6], [1, 86, 47.6], [1, 92, 28.2]], [1, 0, 0], 0, [0, 0, 0]]);
